/**
 * build-retention-fly-bundle.mjs — emit a SINGLE-FILE, import-free bundle of the retention enforcer for
 * mounting as a Fly process-script (memory: mounted process scripts must be single-file — sibling ES imports
 * crash on Fly and stop the operator). Transitively inlines every RELATIVE import (topo-ordered, deduped),
 * strips `export`, drops the relative import lines. SSOT stays the source files; this is a build artifact.
 * Entry = ./enforce-retention-once.mjs. Prints the bundle to stdout.
 */
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
const REL = /^\s*import\s*(?:[\w*{}\s,]+)\s*from\s*'(\.[^']+)';?\s*$/gm;
const seen = new Set(); const chunks = [];
function inline(url) {
  const path = fileURLToPath(url);
  if (seen.has(path)) return; seen.add(path);
  let src = readFileSync(url, 'utf8');
  // resolve + inline this file's relative deps FIRST (so deps precede use)
  const deps = [...src.matchAll(REL)].map((m) => m[1]);
  for (const d of deps) inline(new URL(d, url));
  // strip export keywords and the relative import lines
  src = src.replace(/^export\s+/gm, '').replace(REL, '// [bundled] inlined');
  chunks.push(`// --- ${path.split('/').slice(-2).join('/')} ---\n` + src);
}
inline(new URL('./enforce-retention-once.mjs', import.meta.url));
process.stdout.write('// ⚠️ GENERATED by build-retention-fly-bundle.mjs — do NOT edit; edit source + rebuild.\n' + chunks.join('\n'));
